// n8n Code Node - Extract LinkedIn Profile Data
// Input: $input.all() contains the LinkedIn profile JSON array

const profiles = $input.all();
const extractedData = [];

profiles.forEach((profile) => {
  // Handle different input formats
  let data;

  if (Array.isArray(profile.json)) {
    data = profile.json[0]; // If json is an array, get first element
  } else if (profile.json) {
    data = profile.json; // If json is an object directly
  } else {
    data = profile; // If the profile itself is the data
  }

  // Skip if data is undefined or null
  if (!data || !data.id) {
    console.log('Skipping invalid profile data');
    return;
  }

  // Extract basic information
  const basicInfo = {
    // Personal Information
    linkedinId: data.id,
    firstName: data.firstName,
    lastName: data.lastName,
    fullName: `${data.firstName} ${data.lastName}`,
    publicIdentifier: data.publicIdentifier,
    linkedinUrl: data.linkedinUrl,
    headline: data.headline,

    // Email Information
    email: data.emails?.[0]?.email || null,
    emailDeliverable: data.emails?.[0]?.deliverable || null,
    emailQualityScore: data.emails?.[0]?.qualityScore || null,
    emailStatus: data.emails?.[0]?.status || null,

    // Location
    location: data.location?.linkedinText || null,
    city: data.location?.parsed?.city || null,
    state: data.location?.parsed?.state || null,
    country: data.location?.parsed?.country || null,
    countryCode: data.location?.countryCode || null,

    // Profile Stats
    connectionsCount: data.connectionsCount,
    followerCount: data.followerCount,
    verified: data.verified,
    premium: data.premium,
    openToWork: data.openToWork,

    // About
    about: data.about,

    // Registration
    registeredAt: data.registeredAt,

    // Profile Picture
    profilePictureUrl: data.profilePicture?.url || null,
  };

  // Extract Current Position
  const currentPosition = data.currentPosition?.[0] ? {
    companyName: data.currentPosition[0].companyName,
    companyLinkedinUrl: data.currentPosition[0].companyLinkedinUrl,
    startMonth: data.currentPosition[0].dateRange?.start?.month,
    startYear: data.currentPosition[0].dateRange?.start?.year,
  } : null;

  // Extract Company Website
  const companyWebsite = data.companyWebsites?.[0]?.url || null;
  const companyDomain = data.companyWebsites?.[0]?.domain || null;

  // Extract All Experience
  const experience = data.experience?.map(exp => ({
    position: exp.position,
    companyName: exp.companyName,
    companyLinkedinUrl: exp.companyLinkedinUrl,
    location: exp.location,
    employmentType: exp.employmentType,
    workplaceType: exp.workplaceType,
    duration: exp.duration,
    description: exp.description,
    startDate: exp.startDate?.text || null,
    endDate: exp.endDate?.text || null,
    skills: exp.skills || []
  })) || [];

  // Extract Education
  const education = data.education?.map(edu => ({
    schoolName: edu.schoolName,
    degree: edu.degree,
    fieldOfStudy: edu.fieldOfStudy,
    startYear: edu.startDate?.year,
    endYear: edu.endDate?.year,
    period: edu.period
  })) || [];

  // Extract Skills
  const skills = data.skills?.map(skill => ({
    name: skill.name,
    endorsements: skill.endorsements || null,
    assessments: skill.assessments || null,
    positions: skill.positions || []
  })) || [];

  // Extract Skills Names Only (for easy reference)
  const skillNames = data.skills?.map(skill => skill.name) || [];

  // Combine all data
  const completeProfile = {
    ...basicInfo,
    currentPosition,
    companyWebsite,
    companyDomain,
    experience,
    education,
    skills,
    skillNames,
    // Additional metadata
    totalExperience: experience.length,
    totalEducation: education.length,
    totalSkills: skills.length
  };

  extractedData.push(completeProfile);
});

// Return the extracted data
return extractedData.map(data => ({ json: data }));

// n8n Code Node - Generate AI Email Prompt for Candidate Outreach
// This code creates a prompt to send to Claude/OpenAI API for personalized email generation

const candidateData = $input.first().json;
const jobDescription =  $('Edit Fields').first().json;

// Parse JSON strings from candidate data
const skills = JSON.parse(candidateData.skills || '[]');
const positions = JSON.parse(candidateData.positions || '[]');
const education = JSON.parse(candidateData.education || '[]');
const assessments = JSON.parse(candidateData.assessments || '[]');

// Extract relevant experience matching job requirements
const relevantSkills = skills.filter(skill => 
  jobDescription.skills.some(jobSkill => 
    skill.toLowerCase().includes(jobSkill.toLowerCase()) || 
    jobSkill.toLowerCase().includes(skill.toLowerCase())
  )
);

// Calculate years of experience from positions
const calculateYearsOfExperience = (positions) => {
  let totalMonths = 0;
  positions.forEach(pos => {
    const duration = pos.duration || '';
    const yearMatch = duration.match(/(\d+)\s*yr/);
    const monthMatch = duration.match(/(\d+)\s*mo/);
    if (yearMatch) totalMonths += parseInt(yearMatch[1]) * 12;
    if (monthMatch) totalMonths += parseInt(monthMatch[1]);
  });
  return Math.floor(totalMonths / 12);
};

const yearsOfExperience = calculateYearsOfExperience(positions);

// Create the AI prompt
const aiPrompt = `You are a professional recruiter writing a personalized outreach email to a potential candidate.

**CANDIDATE INFORMATION:**
- Name: ${candidateData.name}
- Email: ${candidateData.email}
- Current Position: ${candidateData.current_job_title || positions[0]?.position || 'N/A'}
- Current Company: ${candidateData.current_company || 'N/A'}
- Location: ${candidateData.location}
- LinkedIn: ${candidateData.linkedin_url}
- Years of Experience: ${yearsOfExperience} years
- Headline: ${candidateData.headline}

**CANDIDATE SKILLS:**
${skills.slice(0, 15).join(', ')}

**RELEVANT MATCHING SKILLS:**
${relevantSkills.length > 0 ? relevantSkills.join(', ') : 'General technical background'}

**RECENT EXPERIENCE:**
${positions.slice(0, 2).map(pos => `- ${pos.position} at ${pos.companyName} (${pos.duration || pos.startDate})`).join('\n')}

**EDUCATION:**
${education.map(edu => `- ${edu.degree} in ${edu.fieldOfStudy} from ${edu.schoolName} (${edu.period})`).join('\n')}

**LINKEDIN ASSESSMENTS PASSED:**
${assessments.length > 0 ? assessments.map(a => `- ${a.name}`).join('\n') : 'None listed'}

**PROFILE SUMMARY:**
${candidateData.profile_summary?.substring(0, 300)}...

---

**JOB OPPORTUNITY:**
- Title: ${jobDescription.Title}
- Department: ${jobDescription.Department}
- Location: ${jobDescription.location}
- Experience Required: ${jobDescription.experience}
- Required Skills: ${jobDescription.skills.join(', ')}

**Job Description:**
${jobDescription.description}

---

**EMAIL REQUIREMENTS:**

Write a professional, personalized cold outreach email with the following guidelines:

1. **Subject Line:** Create an engaging subject line (provide 2 options)

2. **Email Body:**
   - Start with a personalized greeting using their first name
   - Reference 2-3 specific things from their profile (skills, experience, or achievements) that align with the job
   - Highlight why they would be a great fit based on their background
   - Briefly explain the role and its key responsibilities
   - Mention the company culture or unique benefits (keep it professional)
   - Include a clear call-to-action (schedule a call, reply for more info, etc.)
   - Keep it concise (200-250 words max)
   - Maintain a friendly yet professional tone
   - Avoid being too salesy or generic

3. **Formatting:**
   - Use proper paragraphs with spacing
   - Professional sign-off
   - Include placeholder for recruiter name: [Your Name]
   - Include placeholder for company name: [Company Name]

4. **Key Points to Emphasize:**
   - Their ${yearsOfExperience} years of experience matches our ${jobDescription.experience} requirement
   - Their skills in ${relevantSkills.slice(0, 3).join(', ')} are directly relevant
   - Their background with ${candidateData.current_company} shows they have ${jobDescription.Department} experience
   - They are located in ${candidateData.location} which ${candidateData.location.includes(jobDescription.location) ? 'matches' : 'is near'} our ${jobDescription.location} location

Generate a warm, personalized email that makes ${candidateData.name.split(' ')[0]} feel valued and excited about this opportunity.`;

// Return the prompt and metadata
return [{
  json: {
    prompt: aiPrompt,
    candidate_name: candidateData.name,
    candidate_email: candidateData.email,
    candidate_first_name: candidateData.name.split(' ')[0],
    job_title: jobDescription.Title,
    matching_skills_count: relevantSkills.length,
    years_experience: yearsOfExperience,
    // Include original data for reference
    original_candidate_data: candidateData,
    original_job_data: jobDescription
  }
}];

// n8n Code Node - Parse AI Email Response
// Place this node between AI response and email sending node

const aiResponse = $input.first().json;

// Get the AI-generated text (adjust based on your AI provider)
let emailText = '';

// For OpenAI/ChatGPT
if (aiResponse.choices && aiResponse.choices[0]) {
  emailText = aiResponse.choices[0].message.content;
}
// For Anthropic Claude
else if (aiResponse.content && Array.isArray(aiResponse.content)) {
  emailText = aiResponse.content[0].text;
}
// For direct text response
else if (aiResponse.text) {
  emailText = aiResponse.text;
}
// If the response is already the text
else if (typeof aiResponse === 'string') {
  emailText = aiResponse;
}

// Extract subject lines
const subjectMatch = emailText.match(/\*\*Subject Line.*?:\*\*\s*(.*?)(?=\n\n|---)/s);
let subjectLines = [];
if (subjectMatch) {
  const subjectSection = subjectMatch[1];
  subjectLines = subjectSection
    .split('\n')
    .filter(line => line.trim().match(/^\d+\./))
    .map(line => line.replace(/^\d+\.\s*/, '').trim());
}

// Extract email body
const emailBodyMatch = emailText.match(/\*\*Email Body:\*\*\s*(.*?)(?=\n\n---|\n\nBest regards|$)/s);
let emailBody = '';
if (emailBodyMatch) {
  emailBody = emailBodyMatch[1].trim();
} else {
  // If no clear body section, try to get everything after subject lines
  const afterSubject = emailText.split(/---/)[1] || emailText;
  emailBody = afterSubject.replace(/\*\*Email Body:\*\*/g, '').trim();
}

// Clean up the email body - remove markdown formatting if needed
emailBody = emailBody
  .replace(/\*\*/g, '') // Remove bold markdown
  .replace(/\n{3,}/g, '\n\n') // Normalize line breaks
  .trim();

// Convert to HTML format
const emailBodyHtml = emailBody
  .split('\n\n')
  .map(para => `<p>${para.replace(/\n/g, '<br>')}</p>`)
  .join('');

// Get candidate info from previous node (if available)
const previousData = $('Code in JavaScript1').first().json; // Adjust node name
const candidateEmail = previousData?.candidate_email || aiResponse.candidate_email;
const candidateName = previousData?.candidate_first_name || 'there';

// Return formatted data ready for email sending
return [{
  json: {
    // Email fields
    to: candidateEmail,
    subject: subjectLines[0] || `Exciting opportunity for ${candidateName}`,
    subject_option_1: subjectLines[0] || '',
    subject_option_2: subjectLines[1] || '',
    body_text: emailBody,
    body_html: emailBodyHtml,

    // Metadata
    candidate_name: candidateName,
    generated_at: new Date().toISOString(),

    // Original response for reference
    original_ai_response: emailText
  }
}];

return items.map(item => {
  const raw =
    item.json.text ||
    item.json.textPlain ||
    item.json.body ||
    '';

  let userReply = raw;
  let originalMessage = '';

  // 1️⃣ Split Gmail-style reply
  const gmailSplit = raw.split(/\nOn .*wrote:\n/i);

  if (gmailSplit.length > 1) {
    userReply = gmailSplit[0].trim();
    originalMessage = gmailSplit[1];
  }

  // 2️⃣ Remove all quoted ">" characters
  originalMessage = originalMessage
    .split('\n')
    .map(line => line.replace(/^>+\s?/, ''))
    .join('\n')
    .trim();

  // 3️⃣ Extract ONLY the most recent replied message
  // (first meaningful paragraph)
  originalMessage = originalMessage
    .split(/\nOn .*wrote:/i)[0]
    .split(/\nFrom:/i)[0]
    .trim();

  // 4️⃣ Clean signatures from user reply
  userReply = userReply
    .replace(/--\s[\s\S]*/g, '')
    .trim();

  return {
    json: {
      from: item.json.from.value?.[0]?.address || item.json.from,
      subject: item.json.subject,
      userReply,
      originalMessage
    }
  };
});

const input = $input.first().json;
let text = input.text || input.response || '';

// Remove markdown
text = text.replace(/```json\n?/g, '').replace(/```/g, '').trim();

// Parse JSON
let result;
try {
  result = JSON.parse(text);
} catch (e) {
  result = {
    interest_level: 'unclear',
    sentiment: 'neutral',
    next_action: 'wait_for_clarification',
    reasoning: 'Parse error',
    urgency_score: 1,
    confidence_score: 0,
    needs_human_review: true
  };
}

// Add routing flags
result.is_spam = result.interest_level === 'spam_or_irrelevant';
result.is_highly_interested = result.interest_level === 'highly_interested';
result.is_interested = result.interest_level === 'interested';
result.is_not_interested = result.interest_level === 'not_interested';

return [{ json: result }];

